from PIL import Image
import os, glob

def detect(path):
    im = Image.open(path)
    px = im.load()
    w,h = im.size
    def L(x,y):
        r,g,b = px[x,y]
        return (r+g+b)/3.0
    cands=[]
    for y in range(12, h-12, 2):
        for x in range(12, w-12, 2):
            lv = L(x,y)
            if lv > 70:
                continue
            # ring brightness at r=7 and r=10, and check not a large dark region
            ring=0; rn=0
            dark_near=0; near_n=0
            for dy in range(-10,11,2):
                for dx in range(-10,11,2):
                    d2=dx*dx+dy*dy
                    if 36 <= d2 <= 100:
                        ring += L(x+dx,y+dy); rn+=1
                    if d2 <= 16:
                        near_n += 1
                        if L(x+dx,y+dy) < 70:
                            dark_near += 1
            if rn==0: continue
            avg = ring/rn
            # hole: dark center, bright ring, compact dark core
            if avg > 100 and dark_near >= 4 and dark_near < 20 and avg-lv > 40:
                cands.append((avg-lv, x, y, lv, avg, dark_near))
    cands.sort(reverse=True)
    clusters=[]
    for item in cands:
        x,y=item[1],item[2]
        placed=False
        for c in clusters:
            if abs(x-c[0])<12 and abs(y-c[1])<12:
                c[2].append(item)
                placed=True
                break
        if not placed:
            clusters.append([x,y,[item]])
    results=[]
    for x,y,items in clusters:
        # centroid of top items
        sx=sy=sw=0
        for diff,xx,yy,lv,avg,dn in items[:8]:
            sx+=xx*diff; sy+=yy*diff; sw+=diff
        results.append((sx/sw, sy/sw, len(items), items[0][0]))
    results.sort(key=lambda t: -t[3])
    return results

